"""Video captions: English generated by Cloudflare Stream, French translated
from it, either replaceable by a staff upload.

Pipeline, per Stream-ingested video rendition (MediaRef with a stream_uid):

1. The video becomes ready (Stream webhook or sweep) -> `on_video_ready`
   creates an English row (source=generated) and a French row
   (source=translated), and asks Stream to start transcribing English.
2. `advance_captions` (captions scheduler / sweep_captions CLI) polls Stream
   for English tracks still generating. Once English is ready, it fetches the
   English .vtt, translates it, and uploads the result as the French track.
3. A staff upload replaces a track on Stream and marks it source=uploaded,
   which automation never overwrites. A new English upload re-queues a
   machine-translated French track so it follows the corrected English.

Stream lists every ready track in the HLS manifest as a subtitle rendition,
so the existing signed playback URL carries captions with no player-side URL
changes. English is the default language; players pick it unless the viewer
chooses French.
"""
from __future__ import annotations

import uuid

from sqlalchemy import func, select
from sqlalchemy.ext.asyncio import AsyncSession
from sqlalchemy.orm import selectinload

from app.core import stream as stream_module
from app.core import translate as translate_module
from app.core import vtt
from app.core.config import get_settings
from app.core.logging import get_logger
from app.core.stream import StreamError
from app.core.translate import TranslationError
from app.models.models import (
    CaptionSource,
    CaptionStatus,
    MediaCaption,
    MediaRef,
    MediaType,
    Sermon,
    User,
)
from app.services.content_service import ContentError, ensure_editor_can_access

settings = get_settings()
log = get_logger("captions")

SOURCE_LANGUAGE = "en"
TRANSLATED_LANGUAGES = ("fr",)
SUPPORTED_LANGUAGES = (SOURCE_LANGUAGE, *TRANSLATED_LANGUAGES)
LANGUAGE_LABELS = {"en": "English", "fr": "Français"}

# Stream accepts up to 10 MB, but uploads arrive as JSON through this API's
# 2 MB request cap (BodySizeLimitMiddleware). 1 MB is still ~10x a two-hour
# sermon's captions.
MAX_CAPTION_BYTES = 1024 * 1024
# A step (generate kickoff, poll error, translation) that fails this many
# times marks the row ERROR; staff can retry from the portal.
MAX_ATTEMPTS = 5
# Fixed key for pg_try_advisory_xact_lock so several API instances running the
# scheduler don't translate the same track twice.
CAPTIONS_ADVISORY_LOCK_KEY = 0x52504341  # "RPCA"


# ── Pipeline ─────────────────────────────────────────────────────────────────
def _default_source(language: str) -> CaptionSource:
    return CaptionSource.GENERATED if language == SOURCE_LANGUAGE else CaptionSource.TRANSLATED


async def _rows_for_ref(db: AsyncSession, ref: MediaRef) -> dict[str, MediaCaption]:
    rows = (await db.execute(
        select(MediaCaption).where(MediaCaption.media_ref_id == ref.id)
    )).scalars().all()
    return {row.language: row for row in rows}


async def ensure_caption_rows(db: AsyncSession, ref: MediaRef) -> dict[str, MediaCaption]:
    """Create any missing caption rows for a Stream video. Does not commit."""
    rows = await _rows_for_ref(db, ref)
    for language in SUPPORTED_LANGUAGES:
        if language not in rows:
            row = MediaCaption(
                media_ref_id=ref.id,
                language=language,
                status=CaptionStatus.PENDING,
                source=_default_source(language),
                attempts=0,
            )
            db.add(row)
            rows[language] = row
    await db.flush()
    return rows


def _fail(row: MediaCaption, message: str) -> None:
    row.attempts += 1
    row.error_message = message[:1000]
    if row.attempts >= MAX_ATTEMPTS:
        row.status = CaptionStatus.ERROR
    log.warning(
        "caption_step_failed",
        media_ref_id=str(row.media_ref_id), language=row.language,
        attempts=row.attempts, error=message,
    )


async def _kickoff_generation(ref: MediaRef, row: MediaCaption) -> None:
    provider = stream_module.get_provider()
    try:
        # A language exists at most once per Stream video, so clear any
        # earlier track first (re-generation, or a half-finished retry).
        await provider.delete_captions(uid=ref.stream_uid, language=row.language)
        await provider.generate_captions(uid=ref.stream_uid, language=row.language)
    except StreamError as exc:
        _fail(row, str(exc))
        return
    row.status = CaptionStatus.GENERATING
    row.error_message = None


async def on_video_ready(db: AsyncSession, ref: MediaRef) -> None:
    """Called when a Stream video ingest resolves ready. Never raises: the
    caller is the Stream webhook/sweep, which must not fail over captions;
    anything left PENDING is picked up by advance_captions. Does not commit."""
    if not settings.captions_auto_generate:
        return
    if ref.type != MediaType.VIDEO or not ref.stream_uid:
        return
    try:
        rows = await ensure_caption_rows(db, ref)
        source = rows[SOURCE_LANGUAGE]
        if source.status == CaptionStatus.PENDING and source.source == CaptionSource.GENERATED:
            await _kickoff_generation(ref, source)
    except Exception as exc:  # noqa: BLE001 - captions must never break ingest
        log.error(
            "captions_on_ready_failed",
            media_ref_id=str(ref.id), error_type=type(exc).__name__,
        )


async def _translate_track(ref: MediaRef, row: MediaCaption) -> None:
    provider = stream_module.get_provider()
    try:
        source_vtt = await provider.get_captions_vtt(
            uid=ref.stream_uid, language=SOURCE_LANGUAGE
        )
        cues = vtt.parse(source_vtt)
        if not cues:
            raise vtt.VttError("English track has no cues")
        groups = vtt.group_for_translation(cues)
        translated = await translate_module.get_translator().translate(
            [vtt.group_text(g) for g in groups],
            source=SOURCE_LANGUAGE, target=row.language,
        )
        out: list[vtt.Cue] = []
        for group, text in zip(groups, translated, strict=True):
            out.extend(vtt.split_translation(group, text))
        await provider.upload_captions(
            uid=ref.stream_uid, language=row.language,
            vtt=vtt.serialize(out).encode("utf-8"),
        )
    except (StreamError, TranslationError, vtt.VttError) as exc:
        _fail(row, str(exc))
        return
    row.status = CaptionStatus.READY
    row.error_message = None
    log.info(
        "caption_translated",
        media_ref_id=str(ref.id), language=row.language, cues=len(out),
    )


async def _advance_ref(ref: MediaRef, rows: dict[str, MediaCaption]) -> bool:
    """One step for one video. Returns True if anything changed."""
    changed = False
    source = rows.get(SOURCE_LANGUAGE)

    if source is not None and source.source == CaptionSource.GENERATED:
        if source.status == CaptionStatus.PENDING:
            await _kickoff_generation(ref, source)
            changed = True
        elif source.status == CaptionStatus.GENERATING:
            try:
                tracks = await stream_module.get_provider().list_captions(uid=ref.stream_uid)
            except StreamError as exc:
                _fail(source, str(exc))
                return True
            track = next((t for t in tracks if t.language == SOURCE_LANGUAGE), None)
            if track is None:
                # Stream lost the request (or someone deleted it) — ask again.
                source.status = CaptionStatus.PENDING
                changed = True
            elif track.status == "ready":
                source.status = CaptionStatus.READY
                source.error_message = None
                changed = True
                log.info("caption_generated", media_ref_id=str(ref.id), language=SOURCE_LANGUAGE)
            elif track.status == "error":
                source.status = CaptionStatus.PENDING
                _fail(source, "Stream could not generate captions for this video")
                changed = True

    source_ready = source is not None and source.status == CaptionStatus.READY
    for language in TRANSLATED_LANGUAGES:
        row = rows.get(language)
        if row is None or row.status != CaptionStatus.PENDING:
            continue
        if row.source != CaptionSource.TRANSLATED:
            continue
        if source_ready:
            await _translate_track(ref, row)
            changed = True
        elif source is not None and source.status == CaptionStatus.ERROR:
            row.status = CaptionStatus.ERROR
            row.error_message = "English captions failed, so there is nothing to translate"
            changed = True
    return changed


async def advance_captions(db: AsyncSession) -> int | None:
    """One pass over every caption row still in flight. Returns how many
    videos changed, or None if another instance holds the lock."""
    if db.bind is not None and db.bind.dialect.name == "postgresql":
        got = (await db.execute(
            select(func.pg_try_advisory_xact_lock(CAPTIONS_ADVISORY_LOCK_KEY))
        )).scalar()
        if not got:
            return None

    ref_ids = (await db.execute(
        select(MediaCaption.media_ref_id)
        .where(MediaCaption.status.in_((CaptionStatus.PENDING, CaptionStatus.GENERATING)))
        .distinct()
    )).scalars().all()

    changed = 0
    for ref_id in ref_ids:
        ref = await db.get(MediaRef, ref_id)
        if ref is None or not ref.stream_uid:
            continue
        rows = await _rows_for_ref(db, ref)
        if await _advance_ref(ref, rows):
            changed += 1
    await db.commit()
    if changed:
        log.info("captions_advanced", videos=changed)
    return changed


async def backfill_captions(db: AsyncSession, *, execute: bool) -> int:
    """Queue captions for every Stream-ready video that has none yet (videos
    ingested before captions existed). Dry run unless `execute`."""
    refs = (await db.execute(
        select(MediaRef)
        .outerjoin(MediaCaption, MediaCaption.media_ref_id == MediaRef.id)
        .where(
            MediaRef.type == MediaType.VIDEO,
            MediaRef.stream_uid.is_not(None),
            MediaCaption.id.is_(None),
        )
    )).scalars().all()
    queued = 0
    for ref in refs:
        try:
            status = await stream_module.get_provider().get_status(uid=ref.stream_uid)
        except StreamError as exc:
            log.warning("captions_backfill_status_failed", media_ref_id=str(ref.id), error=str(exc))
            continue
        if not (status.state == "ready" and status.ready_to_stream):
            continue
        queued += 1
        if execute:
            await ensure_caption_rows(db, ref)
    if execute:
        await db.commit()
    return queued


# ── Staff (admin portal) ─────────────────────────────────────────────────────
async def _video_ref_for_staff(
    db: AsyncSession, sermon_id: uuid.UUID, actor: User
) -> tuple[Sermon, MediaRef | None]:
    sermon = (await db.execute(
        select(Sermon).where(Sermon.id == sermon_id).options(selectinload(Sermon.media_refs))
    )).scalar_one_or_none()
    if sermon is None:
        raise ContentError("Sermon not found", status_code=404)
    ensure_editor_can_access(sermon, actor, action="manage captions for")
    ref = next(
        (r for r in sermon.media_refs if r.type == MediaType.VIDEO and r.stream_uid),
        None,
    )
    return sermon, ref


def _check_language(language: str) -> None:
    if language not in SUPPORTED_LANGUAGES:
        raise ContentError(
            f"Unsupported caption language '{language}'. "
            f"Supported: {', '.join(SUPPORTED_LANGUAGES)}",
            status_code=422,
        )


async def _require_ref(db: AsyncSession, sermon_id: uuid.UUID, actor: User) -> MediaRef:
    _, ref = await _video_ref_for_staff(db, sermon_id, actor)
    if ref is None:
        raise ContentError(
            "Captions need a processed video. Upload a video and wait for it "
            "to finish processing first.",
            status_code=409,
        )
    return ref


async def list_captions(
    db: AsyncSession, sermon_id: uuid.UUID, actor: User
) -> tuple[bool, list[MediaCaption]]:
    """(captions_available, rows in English-first order)."""
    _, ref = await _video_ref_for_staff(db, sermon_id, actor)
    if ref is None:
        return False, []
    rows = await _rows_for_ref(db, ref)
    return True, [rows[lang] for lang in SUPPORTED_LANGUAGES if lang in rows]


async def get_caption_vtt(
    db: AsyncSession, sermon_id: uuid.UUID, language: str, actor: User
) -> str:
    _check_language(language)
    ref = await _require_ref(db, sermon_id, actor)
    try:
        return await stream_module.get_provider().get_captions_vtt(
            uid=ref.stream_uid, language=language
        )
    except StreamError as exc:
        raise ContentError("No captions in that language yet", status_code=404) from exc


async def upload_caption(
    db: AsyncSession, sermon_id: uuid.UUID, language: str, raw: bytes, actor: User
) -> MediaCaption:
    _check_language(language)
    if len(raw) > MAX_CAPTION_BYTES:
        raise ContentError("Caption file is larger than 1 MB", status_code=413)
    try:
        text = vtt.validate(raw)
    except vtt.VttError as exc:
        raise ContentError(str(exc), status_code=422) from exc
    ref = await _require_ref(db, sermon_id, actor)
    rows = await ensure_caption_rows(db, ref)
    provider = stream_module.get_provider()
    try:
        await provider.delete_captions(uid=ref.stream_uid, language=language)
        await provider.upload_captions(
            uid=ref.stream_uid, language=language, vtt=text.encode("utf-8")
        )
    except StreamError as exc:
        log.error("caption_upload_failed", media_ref_id=str(ref.id), error=str(exc))
        raise ContentError("Could not save captions to the video service", status_code=502) from exc

    row = rows[language]
    row.status = CaptionStatus.READY
    row.source = CaptionSource.UPLOADED
    row.attempts = 0
    row.error_message = None
    if language == SOURCE_LANGUAGE:
        # Corrected English: re-translate any machine-translated track.
        for other in TRANSLATED_LANGUAGES:
            if rows[other].source == CaptionSource.TRANSLATED:
                rows[other].status = CaptionStatus.PENDING
                rows[other].attempts = 0
                rows[other].error_message = None
    await db.commit()
    await db.refresh(row)
    log.info("caption_uploaded", media_ref_id=str(ref.id), language=language, actor=str(actor.id))
    return row


async def regenerate_caption(
    db: AsyncSession, sermon_id: uuid.UUID, language: str, actor: User
) -> MediaCaption:
    """Throw away a track and redo it automatically: English is
    re-transcribed by Stream, French re-translated from English. Also the
    retry for a track in ERROR."""
    _check_language(language)
    ref = await _require_ref(db, sermon_id, actor)
    rows = await ensure_caption_rows(db, ref)
    row = rows[language]
    row.source = _default_source(language)
    row.status = CaptionStatus.PENDING
    row.attempts = 0
    row.error_message = None
    if language == SOURCE_LANGUAGE:
        for other in TRANSLATED_LANGUAGES:
            if rows[other].source == CaptionSource.TRANSLATED:
                rows[other].status = CaptionStatus.PENDING
                rows[other].attempts = 0
                rows[other].error_message = None
        await _kickoff_generation(ref, row)
    else:
        try:
            await stream_module.get_provider().delete_captions(
                uid=ref.stream_uid, language=language
            )
        except StreamError as exc:
            log.warning("caption_delete_failed", media_ref_id=str(ref.id), error=str(exc))
        # Translation itself runs in advance_captions (a long sermon takes a
        # minute or two), not inside this request.
    await db.commit()
    await db.refresh(row)
    return row
